{
  "name": "横河 AQ6370 光谱分析仪",
  "name_en": "Yokogawa AQ6370 Optical Spectrum Analyzer",
  "manufacturer": "Yokogawa",
  "description": "用于测量和分析光信号光谱的光谱分析仪，可执行波长扫描、读取迹线数据与波长轴，并获取分析结果，常用于激光器、光纤器件和光通信实验中的光谱表征。",
  "description_en": "An optical spectrum analyzer used to measure and analyze optical spectra. It can perform wavelength sweeps, read trace data and wavelength axes, and retrieve analysis results for spectral characterization in lasers, fiber devices, and optical communication experiments.",
  "actions": [
    {
      "action_name": "auto-abort",
      "description": "中止正在进行的扫描、校准或其他当前操作。",
      "description_en": "Abort a running sweep, calibration, or other current operation."
    },
    {
      "action_name": "auto-active_trace",
      "description": "定义当前活动迹线。",
      "description_en": "Define the active trace."
    },
    {
      "action_name": "auto-analysis",
      "description": "获取分析结果数据。",
      "description_en": "Get the analysis result data."
    },
    {
      "action_name": "auto-bandwidth",
      "description": "定义测量带宽。",
      "description_en": "Define the measurement bandwidth."
    },
    {
      "action_name": "auto-center_wl",
      "description": "定义中心波长。",
      "description_en": "Define the center wavelength."
    },
    {
      "action_name": "auto-clear",
      "description": "清除状态寄存器。",
      "description_en": "Clear the status registers."
    },
    {
      "action_name": "auto-data",
      "description": "读取当前活动迹线的数据。",
      "description_en": "Read the data of the active trace."
    },
    {
      "action_name": "auto-points",
      "description": "定义扫描点数。",
      "description_en": "Define the number of sweep points."
    },
    {
      "action_name": "auto-query",
      "description": "发送底层查询命令并返回响应。",
      "description_en": "Send a low-level query command and return the response."
    },
    {
      "action_name": "auto-span",
      "description": "定义扫描波长跨度。",
      "description_en": "Define the sweep wavelength span."
    },
    {
      "action_name": "auto-start_sweep",
      "description": "触发并启动一次扫描更新。",
      "description_en": "Trigger and start a sweep update."
    },
    {
      "action_name": "auto-start_wl",
      "description": "定义扫描起始波长。",
      "description_en": "Define the sweep start wavelength."
    },
    {
      "action_name": "auto-stop_wl",
      "description": "定义扫描终止波长。",
      "description_en": "Define the sweep stop wavelength."
    },
    {
      "action_name": "auto-sweep_mode",
      "description": "定义扫描模式。",
      "description_en": "Define the sweep mode."
    },
    {
      "action_name": "auto-wavelength",
      "description": "读取当前活动迹线的波长轴。",
      "description_en": "Read the wavelength axis of the active trace."
    },
    {
      "action_name": "auto-channel",
      "description": "获取指定通道对象。",
      "description_en": "Get the specified channel object."
    }
  ],
  "tag_hints": [
    "optical spectrum analyzer",
    "OSA",
    "wavelength sweep",
    "trace data acquisition",
    "laser spectrum measurement",
    "fiber optics characterization",
    "Yokogawa AQ6370"
  ]
}

